def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = get_translation_client(config)
    parent = f"projects/{config['project_id']}/locations/{config.get('location', 'global')}"
    translated_values = {}
    for key, value in payload['dictionary'].items():
        response = client.translate_text(request={
            "parent": parent,
            "contents": [value],
            "mime_type": "text/plain",
            "source_language_code": payload['source_language'],
            "target_language_code": payload['target_language'],
        }
        )
        translated_values[key] = response.translations[0].translated_text
    return {
        "dictionary": translated_values,
        "source_language": payload['source_language'],
        "target_language": payload['target_language'],
    }

from google.cloud import translate_v3


def get_translation_client(config):
    return translate_v3.TranslationServiceClient()

from typing import Dict, List


def normalize_payload(payload: Dict) -> Dict:
    return {
        'text': payload.get('text', ''),
        'source_language': payload.get('source_language', ''),
        'target_language': payload.get('target_language', ''),
    }


def normalize_response(response: Dict) -> Dict:
    return {
        'text': response.get('translations', [{}])[0].get('translated_text', ''),
        'source_language': response.get('source_language', ''),
        'target_language': response.get('target_language', ''),
    }


def normalize_batch_response(response: List[Dict]) -> List[Dict]:
    return [
        {
            'text': translation.get('translations', [{}])[0].get('translated_text', ''),
            'source_language': translation.get('source_language', ''),
            'target_language': translation.get('target_language', ''),
        }
        for translation in response
    ]

